import {readFileSync} from "node:fs";
import {gunzipSync} from "node:zlib";
import assert from "node:assert/strict";
import {loadP91PublicObservation,type GetBars} from "../lib/stable4-p91-public-observation-feed";
import {p91} from "../lib/stable4-research-decision-observation";
import type {Raw} from "../lib/stable4-public-market-reconstruction";
const H=3600000,M=300000,root=String.raw`C:\Users\dis\Documents\DisDex_Research\WINRATE_DEEP_20261122`,base=String.raw`C:\tmp\disdex-bt-20251001-20261001`;
const load=(p:string):Raw[]=>gunzipSync(readFileSync(p)).toString("utf8").split(/\r?\n/).filter(Boolean).map(x=>JSON.parse(x));
const bin=(s:string)=>load(root+"/p70_binance_same_aster_period_202507_202611/verified_series/"+s+"-1h-20250701-20261118-FUTURES_UM_VERIFIED.jsonl.gz");
const ast=(s:string)=>[
 ...load(root+"/prebaseline_public_20250801_20250924/"+s+"-1h-20250801-20250924"+(s==="BTCUSDT"?"-RESEARCH_M5QA":"")+".jsonl.gz"),
 ...load(base+"/aster-public-v3-h1/"+s+"-1h-20250924-20261001.jsonl.gz"),
 ...load(root+"/forward_public_20261001_20261118/"+s+"-1h-20261001-20261118.jsonl.gz")];
const maps=new Map<string,Map<number,Raw>>();
for(const s of ["PENGUUSDT","BTCUSDT","ETHUSDT"])maps.set("BINANCE|"+s+"|1h",new Map(bin(s).map(x=>[Number(x[0]),x])));
for(const s of ["PENGUUSDT","BTCUSDT"])maps.set("ASTER|"+s+"|1h",new Map(ast(s).map(x=>[Number(x[0]),x])));
maps.set("ASTER|PENGUUSDT|5m",new Map([...load(base+"/aster-public-v3-5m-prefix/PENGUUSDT-5m-20250924-20260803.jsonl.gz"),...load(base+"/aster-public-v3-5m-suffix/PENGUUSDT-5m-20260803-20261001.jsonl.gz")].map(x=>[Number(x[0]),x])));
let requests=0;
const get:GetBars=async(v,s,i,a,b)=>{requests++;const m=maps.get([v,s,i].join("|"))!;const rows:Raw[]=[];for(let t=a;t<b;t+=i==="1h"?H:M){const x=m.get(t);if(x)rows.push(x);}return rows;};
const rows=readFileSync(root+"/results/PRISM7_P91_REAL_1Y_BINANCE_V20_ALL_NATIVE_ENTRY_SCORE_DECISIONS_20261122.jsonl","utf8").trim().split(/\r?\n/).map(x=>JSON.parse(x));
const mismatches:any[]=[],missing:any[]=[],negative:any[]=[],errors:any[]=[];
let accepted=0,matched=0;
async function main(){
 for(const r of rows){
  const t=r.nativeSignalAtUtcH1Close;
  try{
   const input=await loadP91PublicObservation(t+M,get);
   if(!input){missing.push(t);continue;}
   const z=p91(input);
   if(z.gross!==r.ownerP73GrossBeforeM5||z.score!==r.asterClosedM5Check.score||z.pass!==r.final.startsWith("ACCEPT_"))mismatches.push({t,z,expected:r.final});else matched++;
   accepted+=Number(z.pass);
   if(!rows.some(x=>x.nativeSignalAtUtcH1Close===t-H)){
    const non=await loadP91PublicObservation(t-H+M,get);if(non)negative.push(t-H);
   }
   assert.equal(await loadP91PublicObservation(t+M-1,get),undefined);
  }catch(e){errors.push({t,error:String(e)});}
 }
 let rejected=false;try{await loadP91PublicObservation(rows[0].nativeSignalAtUtcH1Close+M,async(...args)=>(await get(...args)).slice(1));}catch{rejected=true;}
 console.log("ROLLING",JSON.stringify({matched,accepted,missing,mismatches,negative,errors,requests,gapRejected:rejected}));
 assert.equal(matched,41);assert.equal(accepted,4);assert.deepEqual(missing,[]);assert.deepEqual(mismatches,[]);assert.deepEqual(negative,[]);assert.deepEqual(errors,[]);assert.equal(rejected,true);
}
main().catch(e=>{console.error(e);process.exitCode=1});
